window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["multi-agent"]={"title":"多智能体系统：用边界、并行与独立验证组织复杂任务","subtitle":"从任务依赖图、通信拓扑和共享状态，到关键路径、移交损失与同源错误，判断何时多智能体真的优于单智能体。","thesis":"多智能体不会创造额外智力；它把上下文、权限和工作分区，并以通信与合并成本换取并行、隔离或独立复核。只有<b>子任务可分、接口明确、结果可验证</b>时，这笔交换才可能划算。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"三个20分钟研究任务加10分钟合并","rule":"关键路径为 max(20,20,20)+10","steps":"70/30≈2.33","interpretation":"加入开销后仅 1.56 倍"}}],"formulas":[{"id":"multi-agent-critical-path","section":3,"formulaIndex":1,"symbols":[{"name":"T","meaning":"公式中各分支、合并和总体的墙钟时间","evidence":"用户等待的并行墙钟下界"},{"name":"parallel","meaning":"多个可并行分支共同执行的调度方案","evidence":"并行墙钟下界"},{"name":"max","meaning":"从所有分支时长中取最长的一条","evidence":"由最慢分支加串行合并决定"},{"name":"i","meaning":"当前遍历的分支编号","evidence":"第 i 条分支时长"},{"name":"merge","meaning":"所有分支完成后的串行合并阶段","evidence":"串行合并时长"},{"name":"Work","meaning":"所有分支和合并阶段累计的总工作成本","evidence":"Work 是总工作成本"},{"name":"W","meaning":"单个分支或合并阶段消耗的工作量","evidence":"分别是各分支和合并工作量"},{"name":"n","meaning":"参与并行执行的分支总数","evidence":"n 是分支数"}]}],"termReviews":[{"section":2,"reviewedAt":"2026-07-27","terms":[{"name":"黑板系统","meaning":"多个工作者异步读写同一版本化共享状态的协作拓扑","purpose":"支持解耦协作、恢复和跨角色汇合","definitionEvidence":"黑板/共享状态","purposeEvidence":"异步协作与恢复"}]},{"section":6,"reviewedAt":"2026-07-27","terms":[{"name":"乐观锁","meaning":"写入时检查读取后的版本是否已被他人修改的并发控制","purpose":"发现并发覆盖而不长期独占共享状态","definitionEvidence":"乐观锁或事件日志","purposeEvidence":"检测并发冲突"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"多智能体系统把任务拆给多个受边界约束的 Agent。","evidence":"多智能体系统把一个任务拆给多个受边界约束的 Agent"},"problem":{"answer":"它用通信成本换并行权限隔离或独立复核。","evidence":"用通信成本换并行、权限隔离或独立复核"},"inputOutput":{"answer":"输入瓶颈依赖接口，输出角色子任务和统一结果。","evidence":"输入是单 Agent 的明确瓶颈、任务依赖和可验收接口，输出是角色化子任务与统一结果"},"mechanism":{"answer":"协调者拆分，工作者执行，最后合并验证。","evidence":"由协调者合并和验证"},"interpretation":{"answer":"收益来自边界和可验证分工而非角色数量。","evidence":"有效分工来自输入、权限、完成条件或验证视角不同"},"boundary":{"answer":"强依赖短任务或接口不清时只会增加开销。","evidence":"增加 Agent 只会复制上下文和错误"}},{"section":2,"definition":{"answer":"拓扑规定多 Agent 的通信和控制结构。","evidence":"输出管理者—工作者、流水线、对等或黑板拓扑"},"problem":{"answer":"它解决四种控制问题应怎样选择的问题。","evidence":"四种拓扑对应四种控制问题"},"inputOutput":{"answer":"输入依赖集中并行共享需求，输出拓扑。","evidence":"输入依赖结构、控制集中度、并行需求和共享状态方式，输出管理者—工作者、流水线、对等或黑板拓扑"},"mechanism":{"answer":"按结构分配消息所有权终止和验收。","evidence":"须指定任务 ID、终止条件和验收者"},"interpretation":{"answer":"拓扑名称只描述协调结构。","evidence":"拓扑名称只描述协调结构"},"boundary":{"answer":"它不保证信息独立或结论正确。","evidence":"不保证参与者信息独立或结论正确"}},{"section":3,"definition":{"answer":"并行案例计算关键路径墙钟总工时和加速比。","evidence":"输出关键路径墙钟、总工时和加速比"},"problem":{"answer":"它解释三条并行研究为何达不到三倍加速。","evidence":"为什么不是3倍加速"},"inputOutput":{"answer":"输入分支准备合并时长，输出墙钟成本加速。","evidence":"输入三条分支时长、重复准备和合并成本，输出关键路径墙钟、总工时和加速比"},"mechanism":{"answer":"最慢分支加合并决定墙钟，所有工作量累加成本。","evidence":"并行墙钟由最慢分支加串行合并决定"},"interpretation":{"answer":"理想二点三三倍加入开销后仅一点五六倍。","evidence":"加入开销后仅 1.56 倍"},"boundary":{"answer":"资源不足依赖和排队会继续降低收益。","evidence":"强依赖和排队会进一步降低收益"}},{"section":4,"definition":{"answer":"任务契约规定子任务输入输出权限和完成证据。","evidence":"任务契约要写输入、输出、权限和完成证据"},"problem":{"answer":"它解决一句去研究竞争对手为何无法可靠合并。","evidence":"为什么难以合并"},"inputOutput":{"answer":"输入范围资料预算权限，输出可合并委派单。","evidence":"输入子任务范围、资料、schema、预算、权限和完成证据，输出可独立执行且可合并的委派单"},"mechanism":{"answer":"提供最小上下文并返回结构化结果来源缺口。","evidence":"工作者返回结构化结果、来源、缺口和置信边界"},"interpretation":{"answer":"契约通过只表示交接可检查。","evidence":"契约通过只表示交接可检查"},"boundary":{"answer":"它不证明事实正确，写权限与自批仍须分离。","evidence":"不表示研究事实正确"}},{"section":5,"definition":{"answer":"依赖图标记可并行分支和必须等待的因果边。","evidence":"输出可并行分支、必须等待的边以及最终聚合路径"},"problem":{"answer":"它决定哪些任务可并行并用验证门可信合并。","evidence":"任务依赖图决定并行，验证门决定可信合并"},"inputOutput":{"answer":"输入子任务约束状态验证，输出调度聚合路径。","evidence":"输入子任务、先后约束、共享状态和验证门，输出可并行分支、必须等待的边以及最终聚合路径"},"mechanism":{"answer":"无依赖分支并行，验证制品再进入聚合器。","evidence":"聚合器只接收经过验证的制品"},"interpretation":{"answer":"图中并行表示调度许可而非必须同时运行。","evidence":"图中并行是调度许可"},"boundary":{"answer":"缺少独立证据时分支仍会共同犯错。","evidence":"多个分支仍会共同犯错"}},{"section":6,"definition":{"answer":"共享状态是带版本所有者来源和冲突的恢复记录。","evidence":"输出带所有者、来源和冲突状态的可恢复记录"},"problem":{"answer":"它防止两个工作者并发更新时最后写入覆盖。","evidence":"最后写入者一定正确吗"},"inputOutput":{"answer":"输入任务事实产物版本，输出版本化记录。","evidence":"输入任务、事实、决策、产物及版本，输出带所有者、来源和冲突状态的可恢复记录"},"mechanism":{"answer":"消息通知变更，乐观锁或事件日志检测冲突。","evidence":"写入用乐观锁或事件日志检测并发冲突"},"interpretation":{"answer":"最后写入不表示更正确。","evidence":"最后写入不表示更正确"},"boundary":{"answer":"冲突必须保留并仲裁，幂等只防重复副作用。","evidence":"幂等任务 ID 只防重复副作用"}},{"section":7,"definition":{"answer":"独立验证用不同数据工具或视角检查候选结论。","evidence":"输入候选结论、数据源、工具和验证者视角"},"problem":{"answer":"它解释五个相同模型为何可能全部出错。","evidence":"为什么仍可能全部错"},"inputOutput":{"answer":"输入候选数据工具视角，输出支持反驳或未知。","evidence":"输出外部证据支持、反驳或不确定结论"},"mechanism":{"answer":"只有信息或验证机制不同才增加独立性。","evidence":"信息或验证机制真正不同才增加独立性"},"interpretation":{"answer":"一致票数本身不是证据。","evidence":"一致票数本身不是证据"},"boundary":{"answer":"共享训练提示检索会造成相关错误。","evidence":"不能用多数票掩盖"}},{"section":8,"definition":{"answer":"控制协议规定终止重试仲裁和反循环条件。","evidence":"终止、重试与反循环是控制协议的一部分"},"problem":{"answer":"它防止 Agent 相互回派形成无限讨论。","evidence":"怎样保证会停"},"inputOutput":{"answer":"输入深度预算进展错误，输出继续重试或停止。","evidence":"输入委派深度、预算、回合、进展证据和工具错误，输出继续、重试、仲裁、人工升级或停止"},"mechanism":{"answer":"回派需新缺口，无进展或预算耗尽则终止。","evidence":"无进展或预算耗尽时终止"},"interpretation":{"answer":"停止只表示不再自动工作。","evidence":"停止表示系统不再自动工作"},"boundary":{"answer":"无法验证必须明确返回不完整。","evidence":"无法验证应明确返回不完整"}},{"section":9,"definition":{"answer":"多智能体评测必须与同任务同预算基线比较。","evidence":"评测必须与同预算单智能体比较"},"problem":{"answer":"它区分结构收益和单纯增加 token 的收益。","evidence":"还是只是多花了四倍 token"},"inputOutput":{"answer":"输入四类方案，输出质量延迟成本移交指标。","evidence":"输入同任务、同预算的单 Agent、多采样、确定性工作流和多 Agent 方案，输出质量、关键路径、总成本、移交和验证指标"},"mechanism":{"answer":"消融角色隔离共享状态并行以定位贡献。","evidence":"消融角色隔离、共享状态和并行以定位收益来源"},"interpretation":{"answer":"多花 token 的提升不能归因于结构。","evidence":"不能归因于结构"},"boundary":{"answer":"少数高并行案例不能代表所有任务。","evidence":"不能代表所有任务"}},{"section":11,"definition":{"answer":"任务树可观测性按父子任务归因等待和成本。","evidence":"输出关键路径时长与按研究、合并、验证、返工拆分的总成本"},"problem":{"answer":"它解释 token 翻倍是并行还是循环委派。","evidence":"怎样知道是正常并行还是循环委派"},"inputOutput":{"answer":"输入追踪父子角色版本成本，输出路径与成本分解。","evidence":"输入 trace ID、父子关系、角色、版本、token、工具、重试和产物哈希，输出关键路径时长与按研究、合并、验证、返工拆分的总成本"},"mechanism":{"answer":"同时报告关键路径和总工时并按阶段拆分。","evidence":"二者同时报告才能识别过度并行"},"interpretation":{"answer":"关键路径解释等待，总工时解释费用。","evidence":"前者解释用户等待，后者解释费用"},"boundary":{"answer":"缓存与排队必须单独归因。","evidence":"不能把节省或延迟都算给多智能体"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>从任务依赖图判断可并行部分；计算关键路径与并行收益上限；设计角色契约和共享状态；评测移交、冲突与同源错误。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>先找单智能体瓶颈，再决定是否拆分<span class=\"dd-badge intuition\">定位</span></h2><p class=\"dd-lead\">把同一个提示复制给五个 Agent，会自然形成团队吗？</p><p>有效分工来自输入、权限、完成条件或验证视角不同，而不是角色名不同。若一个智能体的上下文足够、步骤强依赖且工具调用很短，多智能体只增加重复读题、消息传递和仲裁。适合拆分的信号包括：独立资料源可并行、不同权限需要隔离、候选解可独立产生并验证、单上下文被无关材料污染。</p><p>多智能体系统把一个任务拆给多个受边界约束的 Agent，并由协调者合并和验证。输入是单 Agent 的明确瓶颈、任务依赖和可验收接口，输出是角色化子任务与统一结果。它用通信成本换并行、权限隔离或独立复核；强依赖短任务或接口不清时，增加 Agent 只会复制上下文和错误。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>四种拓扑对应四种控制问题<span class=\"dd-badge eng\">架构</span></h2><p class=\"dd-lead\">管理者—工作者、流水线、对等讨论和黑板系统怎样选择？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>拓扑</th><th>优势</th><th>主要失败</th></tr></thead><tbody><tr><td>管理者—工作者</td><td>责任与预算集中</td><td>管理者成瓶颈</td></tr><tr><td>流水线</td><td>阶段接口清楚</td><td>上游错误层层放大</td></tr><tr><td>对等/辩论</td><td>产生多样候选</td><td>回合膨胀、从众</td></tr><tr><td>黑板/共享状态</td><td>异步协作与恢复</td><td>陈旧写入和冲突</td></tr></tbody></table></div><p>拓扑可以混合，但必须有唯一任务 ID、所有者、终止条件和最终验收者。自由对话不是协调协议。</p><p>拓扑选择输入依赖结构、控制集中度、并行需求和共享状态方式，输出管理者—工作者、流水线、对等或黑板拓扑。每种拓扑用不同消息和所有权规则工作，并须指定任务 ID、终止条件和验收者。拓扑名称只描述协调结构，不保证参与者信息独立或结论正确。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>完整示例：三条并行研究线能节省多少时间<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">三个20分钟研究任务加10分钟合并，为什么不是3倍加速？</p><p>单智能体串行完成三项研究和合并需要 20+20+20+10=<b>70分钟</b>。三名工作者并行时关键路径为 max(20,20,20)+10=<b>30分钟</b>，理想加速 70/30≈<b>2.33×</b>。若每个工作者还需5分钟重复读背景、合并因冲突增至20分钟，则并行总时长为25+20=45分钟，加速只剩1.56×；总工时从70增至95分钟。</p><div class=\"dd-formula\" data-formula-id=\"multi-agent-critical-path\" data-display=\"mathml\"><math display=\"block\" aria-label=\"并行墙钟时间至少等于最长分支时间加串行合并时间，总工作成本等于所有分支和合并工作量之和\"><msub><mi>T</mi><mtext>parallel</mtext></msub><mo>≥</mo><munder><mi>max</mi><mi>i</mi></munder><mo>(</mo><msub><mi>T</mi><mi>i</mi></msub><mo>)</mo><mo>+</mo><msub><mi>T</mi><mtext>merge</mtext></msub><mo>;</mo><mi>Work</mi><mo>=</mo><munderover><mo>∑</mo><mi>i</mi><mi>n</mi></munderover><msub><mi>W</mi><mi>i</mi></msub><mo>+</mo><msub><mi>W</mi><mtext>merge</mtext></msub></math></div><p class=\"dd-formula-note\"><code>Tparallel</code> 是用户等待的并行墙钟下界，<code>Ti</code> 是第 i 条分支时长，<code>Tmerge</code> 是串行合并时长；<code>Work</code> 是总工作成本，<code>Wi</code> 与 <code>Wmerge</code> 分别是各分支和合并工作量，<code>n</code> 是分支数。</p><p>因此并行优化的是墙钟时间，不一定降低 token 或费用。强依赖链无法越过关键路径，盲目加 Agent 只提高总成本。</p><p>并行案例输入三条分支时长、重复准备和合并成本，输出关键路径墙钟、总工时和加速比。并行墙钟由最慢分支加串行合并决定，而总成本累加所有分支工作量；70/30≈2.33 倍是理想值，加入开销后仅 1.56 倍。计算假设资源充足且分支独立，强依赖和排队会进一步降低收益。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>任务契约要写输入、输出、权限和完成证据<span class=\"dd-badge eng\">委派</span></h2><p class=\"dd-lead\">一句“去研究竞争对手”为什么难以合并？</p><p>每个子任务声明范围、允许资料、输出 schema、预算、截止、不可做事项、来源要求和机器可检查的完成条件。管理者交付最小充分上下文，而不是整段历史；工作者返回结果、证据、未解决问题和置信边界，不返回未经结构化的长聊天记录。</p><p>权限按角色分配：研究者只读，执行者可写但不能自批，验证者不能修改被验证产物。这样多智能体带来的隔离才是真实控制。</p><p>任务契约输入子任务范围、资料、schema、预算、权限和完成证据，输出可独立执行且可合并的委派单。管理者提供最小上下文，工作者返回结构化结果、来源、缺口和置信边界。契约通过只表示交接可检查，不表示研究事实正确；写权限和自我批准仍必须分离。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：任务依赖图决定并行，验证门决定可信合并<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">哪些箭头表示可以并行，哪些箭头是必须等待的因果依赖？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 325\" role=\"img\" aria-label=\"管理者把任务拆为三个并行工作者写入版本化共享状态，独立验证后由聚合者合并\"><defs><marker id=\"ma28\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><rect x=\"20\" y=\"30\" width=\"150\" height=\"58\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"95\" y=\"55\" text-anchor=\"middle\" class=\"svg-t\">管理者</text><text x=\"95\" y=\"76\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">依赖图 · 契约 · 预算</text><path d=\"M95,88 L95,120\" stroke=\"#788293\"/><path d=\"M95,120 L240,120\" stroke=\"#788293\"/><path d=\"M95,120 L95,140\" stroke=\"#788293\" marker-end=\"url(#ma28)\"/><path d=\"M240,120 L240,140\" stroke=\"#788293\" marker-end=\"url(#ma28)\"/><path d=\"M385,120 L385,140\" stroke=\"#788293\" marker-end=\"url(#ma28)\"/><path d=\"M240,120 L385,120\" stroke=\"#788293\"/><rect x=\"25\" y=\"145\" width=\"140\" height=\"70\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><rect x=\"170\" y=\"145\" width=\"140\" height=\"70\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><rect x=\"315\" y=\"145\" width=\"140\" height=\"70\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"95\" y=\"174\" text-anchor=\"middle\" class=\"svg-t\">工作者 A</text><text x=\"240\" y=\"174\" text-anchor=\"middle\" class=\"svg-t\">工作者 B</text><text x=\"385\" y=\"174\" text-anchor=\"middle\" class=\"svg-t\">工作者 C</text><text x=\"95\" y=\"198\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">不同资料 / 只读</text><text x=\"240\" y=\"198\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">不同资料 / 只读</text><text x=\"385\" y=\"198\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">不同资料 / 只读</text><path d=\"M95,215 L95,252\" stroke=\"#788293\" marker-end=\"url(#ma28)\"/><path d=\"M240,215 L240,252\" stroke=\"#788293\" marker-end=\"url(#ma28)\"/><path d=\"M385,215 L385,252\" stroke=\"#788293\" marker-end=\"url(#ma28)\"/><rect x=\"25\" y=\"257\" width=\"430\" height=\"55\" rx=\"9\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"240\" y=\"281\" text-anchor=\"middle\" class=\"svg-t\">版本化共享状态</text><text x=\"240\" y=\"301\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">结果 + 来源 + 假设 + 冲突；禁止无主覆盖</text><path d=\"M455,284 L505,284\" stroke=\"#788293\" marker-end=\"url(#ma28)\"/><rect x=\"510\" y=\"225\" width=\"200\" height=\"87\" rx=\"9\" fill=\"#21252d\" stroke=\"#cf7c72\"/><text x=\"610\" y=\"252\" text-anchor=\"middle\" class=\"svg-t\">独立验证与聚合</text><text x=\"610\" y=\"276\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">证据 / 测试 / 冲突仲裁</text><text x=\"610\" y=\"298\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">缺口回派，不靠投票掩盖</text><path d=\"M170,59 L610,59 L610,225\" fill=\"none\" stroke=\"#d3a05a\" stroke-dasharray=\"6 5\" marker-end=\"url(#ma28)\"/><text x=\"420\" y=\"48\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">管理者只接收可验证制品</text></svg><figcaption>图 1　并行由依赖图证明，可信度由独立验证建立；聊天数量不是系统能力。</figcaption></figure><p>依赖图输入子任务、先后约束、共享状态和验证门，输出可并行分支、必须等待的边以及最终聚合路径。无依赖分支并行写入版本化状态，聚合器只接收经过验证的制品。图中并行是调度许可，不是强制同时运行；缺乏独立证据时多个分支仍会共同犯错。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>共享状态必须版本化，消息只负责通知<span class=\"dd-badge eng\">一致性</span></h2><p class=\"dd-lead\">两个工作者同时更新同一结论，最后写入者一定正确吗？</p><p>把任务、事实、决策、制品和验证结果写入带版本的共享状态；消息传递只携带 ID 和变更摘要。写入使用所有者、乐观锁或事件日志，冲突时保留两种候选并交给仲裁者，不能最后写者覆盖。</p><p>每条结论附来源、生成者、时间、适用范围和状态。工作者重试时使用幂等任务 ID，避免产出重复分支或重复副作用。</p><p>共享状态输入任务、事实、决策、产物及版本，输出带所有者、来源和冲突状态的可恢复记录。消息只通知 ID 和变更，写入用乐观锁或事件日志检测并发冲突。最后写入不表示更正确；冲突必须保留候选并仲裁，幂等任务 ID 只防重复副作用。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>独立 Agent 不等于独立证据<span class=\"dd-badge eng\">边界</span></h2><p class=\"dd-lead\">五个相同模型一致，为什么仍可能全部错？</p><p>相同模型、提示、检索库和训练数据会产生相关错误。增加角色口吻不会增加机制多样性。更强的验证来自不同数据源、不同工具、可执行测试、形式规则或真正独立的模型/人员，并应防验证者看到候选后被锚定。</p><div class=\"dd-note warn\"><b>初学者最易混淆：</b>多次调用是多个进程，不是多个独立知识源；共识必须经过外部证据校验。</div><p>独立验证输入候选结论、数据源、工具和验证者视角，输出外部证据支持、反驳或不确定结论。不同模型调用只有在信息或验证机制真正不同才增加独立性；一致票数本身不是证据。共享训练数据、提示和检索库会造成相关错误，不能用多数票掩盖。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>终止、重试与反循环是控制协议的一部分<span class=\"dd-badge eng\">可靠性</span></h2><p class=\"dd-lead\">Agent A 让 B 检查，B 又让 A 补充，怎样保证会停？</p><p>设置委派深度、每角色预算、最大回合、无进展判据和唯一完成状态；每次回派必须指出新的缺口与验证方法。工具错误采用有界重试，逻辑冲突交仲裁，无法验证则升级人工或返回不完整，不允许无限“再讨论一次”。</p><p>控制协议输入委派深度、预算、回合、进展证据和工具错误，输出继续、重试、仲裁、人工升级或停止。每次回派必须带来新缺口和验证方法，无进展或预算耗尽时终止。停止表示系统不再自动工作，不表示任务已经成功；无法验证应明确返回不完整。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>评测必须与同预算单智能体比较<span class=\"dd-badge eng\">实验</span></h2><p class=\"dd-lead\">成功率高了，是多智能体结构好，还是只是多花了四倍 token？</p><p>基线包含单智能体、单智能体等预算多采样、确定性并行工作流和多智能体。报告任务成功、关键路径延迟、总token/工具成本、重复工作、移交丢失、冲突率、无效回合、验证发现率和人工介入。</p><p>做消融：去掉角色隔离、共享状态、独立验证或并行，定位收益来源。按可并行度、依赖深度和任务长度切片，避免用最适合并行的少数案例代表所有任务。</p><p>多智能体评测输入同任务、同预算的单 Agent、多采样、确定性工作流和多 Agent 方案，输出质量、关键路径、总成本、移交和验证指标。消融角色隔离、共享状态和并行以定位收益来源。成功率提高若只因多花 token 不能归因于结构，少数高度可并行案例也不能代表所有任务。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">多智能体首先是分布式系统问题，其次才是提示词问题。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>Agent越多越聪明</td><td>只增加并行/隔离，也增加通信成本</td></tr><tr><td>角色名不同就有多样性</td><td>需不同信息、权限或验证机制</td></tr><tr><td>多数票可解决冲突</td><td>相关错误需要外部证据</td></tr><tr><td>共享聊天就是共享状态</td><td>需版本、所有者与来源</td></tr><tr><td>并行一定省钱</td><td>常缩短墙钟时间却增加总工时</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>Agent循环、任务图、并发与权限</td></tr><tr><td><b>本页核心</b></td><td>拓扑、契约、关键路径、共享状态、验证</td></tr><tr><td>相邻</td><td>工作流编排、Agent记忆、人在回路</td></tr><tr><td>工程</td><td>幂等、锁、事件日志、可观测性</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">11</span>成本与可观测性必须按任务树归因<span class=\"dd-badge eng\">运营</span></h2><p class=\"dd-lead\">总token突然翻倍，怎样知道是正常并行还是循环委派？</p><p>每个根任务生成 trace ID，子任务记录 parent ID、角色、输入版本、开始/结束、模型、token、工具、重试和产物哈希。仪表盘同时显示关键路径时间与总工时：前者解释用户等待，后者解释费用。按“研究、合并、验证、返工”拆成本，才能发现聚合器过度总结或工作者重复检索。</p><p>设置分支预算和全局预算；子任务超额不能自行再委派，而要向所有者报告当前证据、缺口和继续工作的边际收益。对共享缓存记录命中与来源，避免因缓存节省被误归因于多智能体架构。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>信号</th><th>可能问题</th><th>诊断</th></tr></thead><tbody><tr><td>总工时高、关键路径低</td><td>过度并行</td><td>比较闲置/重复产物</td></tr><tr><td>回派深度持续增长</td><td>完成条件不清</td><td>检查缺口是否产生新证据</td></tr><tr><td>合并成本超过分支</td><td>输出契约不一致</td><td>统计解析与冲突类型</td></tr></tbody></table></div><p>任务树可观测性输入 trace ID、父子关系、角色、版本、token、工具、重试和产物哈希，输出关键路径时长与按研究、合并、验证、返工拆分的总成本。前者解释用户等待，后者解释费用；二者同时报告才能识别过度并行。缓存命中和外部排队需单独归因，不能把节省或延迟都算给多智能体。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">12</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>证明单智能体瓶颈</li><li>画任务依赖与关键路径</li><li>选择拓扑并定义角色契约</li><li>分配最小上下文和权限</li><li>并行执行并写版本化状态</li><li>独立验证结果与证据</li><li>仲裁冲突并回派具体缺口</li><li>按完成条件终止并对比基线</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">13</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>多智能体加速的上限由什么决定？</li><li>角色名为何不产生真正独立性？</li><li>共享聊天为何不能替代共享状态？</li><li>怎样防止循环委派？</li><li>如何证明多智能体值得？</li><li>假设“多智能体系统：用边界、并行与独立验证组织复杂任务”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>任务依赖图的关键路径和不可并行的合并阶段。</li><li>相同模型、信息和验证机制仍会共享盲点。</li><li>聊天缺少版本、所有者、冲突检测和稳定来源。</li><li>限制深度/预算/回合，要求具体新缺口并设置无进展终止。</li><li>与同预算单智能体和确定性并行基线比较质量、延迟、总成本及失败。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2308.08155\" target=\"_blank\" rel=\"noopener\">AutoGen</a>：多智能体会话框架</li><li><a href=\"https://arxiv.org/abs/2303.17760\" target=\"_blank\" rel=\"noopener\">CAMEL</a>：角色协作与社会模拟</li><li><a href=\"https://arxiv.org/abs/2308.00352\" target=\"_blank\" rel=\"noopener\">MetaGPT</a>：结构化软件角色与制品</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
